\title{The CRT-Split No-Go:\\ Why $N$-Alone Iteration Cannot Factor in $\mathrm{poly}(\log N)$}
\author{Aristotle}
\date{11 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $N = pq$ be a semiprime with $p \neq q$ prime. We give a complete structural analysis of
the family of factoring procedures that iterate a map manufactured from $N$ alone --- a
polynomial, or more generally a straight-line program over $(+,-,\times,{}^{-1})$ with
arbitrary integer constants --- and extract a factor by taking greatest common divisors of
differences along the trajectory.

Two facts organise everything. \emph{Fact~1 (reveal criterion):} $\gcd(d,N)$ is a nontrivial
divisor of $N$ if and only if exactly one of $p \mid d$, $q \mid d$ holds. \emph{Fact~2
(CRT-blindness):} iteration of an integer polynomial commutes with reduction, and a
straight-line program all of whose inversions succeed commutes with \emph{every} ring
homomorphism out of $\Z/N$, hence with both Chinese Remainder projections. Together they give
the \emph{reveal characterisation}: a factor appears at times $(s,t)$ exactly when the mod-$p$
orbit closes between $s$ and $t$ exclusive-or the mod-$q$ orbit does. Hence the first reveal
time is exactly $\min(T_p, T_q)$, the smaller of the two closure times.

We then quantify $T_p$ in three exhaustive regimes. For generic nonlinear maps we prove the
exact birthday law --- among all $n^n$ maps of an $n$-element set exactly
$(n-1)^{\underline{T}} n^{\,n-T}$ have a collision-free orbit prefix of length $T+1$ --- its
Gaussian tail, a two-sided threshold window at $T \asymp \sqrt n$, and, via a layer-cake
identity, that the \emph{average} first closure time lies between $\lfloor\sqrt n\rfloor/2$ and
$3(\lfloor\sqrt n\rfloor+1)$; any tortoise-and-hare detector inherits an average lower bound of
$\lfloor\sqrt n\rfloor/4$. On the reduced state space this is $\Theta(\sqrt p) =
\Theta(N^{1/4})$. For smoothness-dependent maps the Pollard $p-1$ reveal time is exactly
$\min(\ord_p a, \ord_q a)$. For structurally simple maps a reveal forces a time gap
$\ge \min(p,q)$, hence superpolynomial in $\log N$. Finally, a rigidity dichotomy shows that
every straight-line computation is either CRT-blind or produces a non-unit which is $0$ or
\emph{is} a nontrivial factor: division is the only escape from polynomiality, and a failed
division is the factorisation.
\end{abstract}

\section{Introduction}

\subsection{The question}

A recurring intuition about integer factorisation is that $N$ must contain its factors in a
directly accessible way, so that some sufficiently clever function of $N$, iterated a modest
number of times, ought to pull them out. Historically the intuition has been productive:
Pollard's rho and Pollard's $p-1$ methods are exactly of this form. This paper makes the
intuition precise and refutes it.

\begin{definition}[The $N$-explicit iteration model]
Given $N$, choose a seed $x_0 \in \Z$ and a map $f$ built from the ring operations $+,-,\times$
(and, in the extended model, division) applied to the variable and to integer constants read
off $N$. Compute $x_{n+1} = f(x_n)$ modulo $N$ and output $\gcd(x_t - x_s, N)$ for pairs
$s < t$, stopping when this is a nontrivial divisor of $N$.
\end{definition}

The main result is that no instance runs in $\mathrm{poly}(\log N)$ steps, for a structural
reason admitting a complete three-way classification.

\subsection{Overview}

(1)~The reveal mechanism is unique (\S\ref{sec:fact1}): a gcd is nontrivial exactly when the
two Chinese Remainder components disagree about vanishing. (2)~The model is symmetric
(\S\ref{sec:fact2}, \S\ref{sec:sle}). (3)~Therefore the reveal is a one-sided cycle closure
(\S\ref{sec:reveal}), of time exactly $\min(T_p,T_q)$. (4)~Every regime of closure behaviour is
slow (\S\ref{sec:regimec}, \S\ref{sec:birthday}, \S\ref{sec:sle}).

\section{Fact 1: the reveal criterion}\label{sec:fact1}

\begin{definition}
For $N > 1$ and $d \in \Z$ we say $d$ \emph{reveals a factor of $N$}, written $\Rev_N(d)$, if
$1 < \gcd(d,N) < N$.
\end{definition}

\begin{lemma}\label{lem:dvdgcd}
If $r \mid N$ then $r \mid \gcd(d,N)$ if and only if $r \mid d$.
\end{lemma}

\begin{proof}
If $r \mid \gcd(d,N)$ then $r \mid d$ since $\gcd(d,N) \mid d$. Conversely, if $r \mid d$ and
$r \mid N$ then $r$ divides their gcd.
\end{proof}

\begin{theorem}[Fact 1; the exclusive-or criterion]\label{thm:fact1}
Let $N = pq$ with $p \neq q$ prime. For every $d \in \Z$,
\[
  \Rev_{pq}(d) \iff \big(p \mid d\big) \XOR \big(q \mid d\big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write $g = \gcd(d,N)$, so $g \mid N$ and, by Lemma~\ref{lem:dvdgcd}, $p \mid g \iff p \mid d$
and $q \mid g \iff q \mid d$.

($\Rightarrow$) Suppose $1 < g < N$. If $p \mid g$ then $q \nmid g$, since coprimality of
$p,q$ would force $pq \mid g$, i.e.\ $g \ge N$. If $p \nmid g$, then either $q \mid g$, or
neither prime divides $g$; in the latter case $g$ is coprime to $N$ and divides $N$, so $g=1$,
contradicting $g > 1$.

($\Leftarrow$) If $p \mid g$ and $q \nmid g$, then $g \ge p > 1$ and $g \neq N$ because
$q \mid N$ but $q \nmid g$. The other case is symmetric.
\end{proof}

\begin{theorem}[Fact 1, general modulus]
For $N > 1$ and $d \in \Z$,
\[
  \Rev_N(d) \iff \big(\exists\, r \text{ prime},\ r \mid N,\ r \mid d\big) \text{ and }
  N \nmid d.
\]
\end{theorem}

\begin{proof}[Proof sketch]
$\gcd(d,N) > 1$ iff it has a prime divisor, necessarily a common prime divisor of $d$ and $N$;
and $\gcd(d,N) = N$ exactly when $N \mid d$.
\end{proof}

A reveal is thus \emph{partial agreement} across the CRT decomposition: total agreement
($N \mid d$) and total disagreement ($\gcd = 1$) are both invisible.

\section{Fact 2: $N$-explicit maps are CRT-blind}\label{sec:fact2}

\begin{definition}
For $f \in \Z[X]$ and $x_0 \in \Z$ let $\mathcal{O}_f(x_0,n) = f^{\circ n}(x_0)$. For a modulus
$m$, the \emph{reduced orbit} $\overline{\mathcal{O}}^{\,m}_f(x_0,n) \in \Z/m$ is the orbit of
$\bar x_0$ under the reduced polynomial $\bar f \in (\Z/m)[X]$.
\end{definition}

\begin{theorem}[Functoriality]\label{thm:funct}
For all $f, m, x_0, n$: $\ \mathcal{O}_f(x_0,n) \bmod m = \overline{\mathcal{O}}^{\,m}_f(x_0,n)$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $n$, using compatibility of polynomial evaluation with reduction:
$\overline{f(z)} = \bar f(\bar z)$.
\end{proof}

\begin{theorem}[Blindness]\label{thm:blind}
If $\bar f = \bar g$ in $(\Z/m)[X]$ and $x_0 \equiv y_0 \pmod m$, then
$\overline{\mathcal{O}}^{\,m}_f(x_0,n) = \overline{\mathcal{O}}^{\,m}_g(y_0,n)$ for all $n$.
\end{theorem}

\begin{corollary}
If $m \mid x_0 - y_0$ then $m \mid \mathcal{O}_f(x_0,n) - \mathcal{O}_f(y_0,n)$ for all $n$.
\end{corollary}

\begin{proof}
Induction using $a - b \mid f(a) - f(b)$ for integer polynomials.
\end{proof}

Theorem~\ref{thm:blind} is the precise content of ``an $N$-explicit map does not split the
CRT'': the mod-$p$ dynamics sees only $f \bmod p$ and $x_0 \bmod p$. Making the map behave
differently in the two components requires reducing it mod $p$ deliberately, i.e.\ already
possessing $p$.

\section{The reveal is an exclusive one-sided closure}\label{sec:reveal}

\begin{theorem}[Reveal characterisation]\label{thm:revealchar}
Let $N = pq$ with $p \neq q$ prime, $f \in \Z[X]$, $x_0 \in \Z$, $s < t$, and write
$x_n = \mathcal{O}_f(x_0,n)$. Then $\Rev_{pq}(x_t - x_s)$ holds if and only if
\[
  \Big(\overline{\mathcal{O}}^{\,p}_f(x_0,t) = \overline{\mathcal{O}}^{\,p}_f(x_0,s)\Big)
  \XOR
  \Big(\overline{\mathcal{O}}^{\,q}_f(x_0,t) = \overline{\mathcal{O}}^{\,q}_f(x_0,s)\Big).
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:fact1} the left side is $(p \mid x_t - x_s) \XOR (q \mid x_t - x_s)$, and by
Theorem~\ref{thm:funct}, $m \mid x_t - x_s$ iff the reduced orbits agree at $s$ and $t$.
\end{proof}

\begin{definition}
The reduced orbit \emph{closes at time $t$} if it agrees at $t$ with its value at some $s < t$.
Write $T_m$ for the least such $t$.
\end{definition}

\begin{theorem}[Pigeonhole and the rho shape]
$T_m \le m$ for every $f, x_0$ and $m \ge 1$; and after a closure at $(s,t)$ the reduced orbit
is periodic with period $t-s$ from time $s$ onwards.
\end{theorem}

\begin{theorem}[No reveal before the first closure]\label{thm:norev}
If $t < \min(T_p, T_q)$ then $\gcd(x_t - x_s, N) = 1$ for every $s < t$.
\end{theorem}

\begin{theorem}[Reveal at the minimum]\label{thm:revmin}
If $T_p \neq T_q$ then, with $t^\ast = \min(T_p,T_q)$, there is $s < t^\ast$ with
$\Rev_N(x_{t^\ast} - x_s)$.
\end{theorem}

\begin{proof}[Proof sketch]
Say $T_p < T_q$. At time $T_p$ the mod-$p$ orbit repeats an earlier value at some $s < T_p$,
while the mod-$q$ orbit repeats nothing, so exactly one branch of the exclusive-or of
Theorem~\ref{thm:revealchar} holds.
\end{proof}

\begin{corollary}
For an $N$-explicit iteration whose two closure times differ, the first reveal time is exactly
$\min(T_p,T_q)$: a statistic of the reduced dynamics in a space of size about $\sqrt N$.
\end{corollary}

\begin{theorem}[Simultaneous closure is blind]
If both reduced orbits close at the same pair $(s,t)$, no factor is revealed at $(s,t)$; indeed
$\gcd(x_t - x_s, N) = N$.
\end{theorem}

\section{Regime (c): structurally simple maps}\label{sec:regimec}

\begin{lemma}
For $f = X+1$ one has $\mathcal{O}_f(x_0,n) = x_0 + n$.
\end{lemma}

\begin{theorem}
For $N = pq$ and $s < t$, the successor iteration reveals a factor at $(s,t)$ iff
$(p \mid t-s) \XOR (q \mid t-s)$. Consequently any reveal satisfies $t - s \ge \min(p,q)$, and
in particular $t \ge \min(p,q)$.
\end{theorem}

\begin{theorem}[Balanced semiprimes]
If $p < q \le 2p$ then any reveal time for the successor iteration satisfies $pq \le 2t^2$,
i.e.\ $t \ge \sqrt{N/2}$.
\end{theorem}

\begin{proof}
$t \ge p$ and $q \le 2p$ give $pq \le 2p^2 \le 2t^2$.
\end{proof}

\begin{theorem}[Superpolynomiality]\label{thm:superpoly}
For every $c, k \in \mathbb{N}$ there exist primes $p < q \le 2p$ such that, with $N = pq$,
every revealing pair $(s,t)$ for the successor iteration satisfies $t > c\,(\log_2 N)^k$.
\end{theorem}

\begin{proof}[Proof sketch]
Choose $p$ large and, by Bertrand's postulate, $q$ with $p < q \le 2p$, so
$\log_2 N \le 2\log_2 p + 2$. Any reveal has $t \ge p \ge 2^L$ with $L = \lfloor \log_2 p
\rfloor$. Since $c' L^k < 2^L$ for all large $L$ (with $c' = c\,4^k$), we get
$c(\log_2 N)^k \le c' L^k < 2^L \le t$ once $p$ is large enough.
\end{proof}

\begin{theorem}[Barrier 5]
For a constant map $f \equiv c$ and any $1 \le s < t$ we have $x_s = x_t$, so
$\gcd(x_t - x_s, N) = N$: no factor is ever revealed.
\end{theorem}

\begin{theorem}
For $f = X+1$ and any seed, $T_m = m$ exactly --- the pigeonhole bound is attained.
\end{theorem}

\section{Regime (a): the birthday law}\label{sec:birthday}

Let $S$ be a set of $n$ elements (for us $S = \Z/p$, $n = p$) and consider all $n^n$ maps
$S \to S$, the standard model for generic reduced dynamics. Fix $a \in S$.

\begin{definition}
The \emph{orbit prefix of length $T+1$} is $a, f(a), \dots, f^{[T]}(a)$; it is
\emph{collision-free} ($\Inj_T(f)$) if these values are pairwise distinct. Let
$A_T = \#\{f : \Inj_T(f)\}$, and let the \emph{closure time} $\tau(f)$ be the least $T$ with
$\neg\,\Inj_T(f)$; by pigeonhole $\tau(f) \le n$.
\end{definition}

\begin{theorem}[Exact birthday law]\label{thm:birthday}
For $T < n$,
\[
  A_T = (n-1)^{\underline{T}}\, n^{\,n-T} = (n-1)(n-2)\cdots(n-T)\, n^{\,n-T},
  \qquad\text{i.e.}\qquad
  \frac{A_T}{n^n} = \prod_{i=1}^{T}\Big(1 - \frac{i}{n}\Big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $T$ via a fibration. The key input is \emph{locality of iteration}: the prefix
depends only on the values of $f$ at earlier prefix points. Define the \emph{reset} map
$\rho(f)$ to be $f$ with its value at $f^{[T]}(a)$ overwritten by $a$. Then $\rho$ preserves
collision-freeness at level $T$; each fiber of $\rho$ inside the level-$T$ set consists of the
$n$ updates of a base map at that position, so has size exactly $n$; and within a fiber exactly
$n - (T+1)$ maps survive to level $T+1$, namely those whose value there avoids the $T+1$ points
already used. Hence $A_{T+1} = \frac{n-(T+1)}{n} A_T$ with $A_0 = n^n$.
\end{proof}

For $n = 4$ and $T = 2$ the formula predicts $3\cdot 2\cdot 4^2 = 96$ collision-free maps out of
$256$, in agreement with exhaustive enumeration.

\begin{theorem}[Two-sided tails]\label{thm:tails}
For $T < n$,
\[
  \Big(1 - \frac{T(T+1)}{2n}\Big) n^n \;\le\; A_T \;\le\;
  \exp\!\Big(-\frac{T(T+1)}{2n}\Big) n^n .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply the two halves of Weierstrass' product inequality, $1 - \sum c_i \le \prod(1-c_i) \le
\exp(-\sum c_i)$ for $0 \le c_i \le 1$, to the exact product of Theorem~\ref{thm:birthday} with
$c_i = i/n$ and $\sum_{i \le T} i = T(T+1)/2$.
\end{proof}

\begin{corollary}[Threshold window]
If $T(T+1) \le n$ then $A_T \ge n^n/2$; if $4n \le T(T+1)$ then $A_T \le n^n/4$, using
$e^{-2} \le 1/4$. The collision-free fraction therefore passes from $\ge 1/2$ to $\le 1/4$
inside the window $\sqrt n \lesssim T \lesssim 2\sqrt n$: the birthday exponent $1/2$ is sharp
from both sides.
\end{corollary}

\subsection{The average closure time is $\Theta(\sqrt n)$}

\begin{theorem}[Layer cake]\label{thm:layer}
$\displaystyle \sum_{f : S \to S} \tau(f) = \sum_{T=0}^{n-1} A_T$.
\end{theorem}

\begin{proof}[Proof sketch]
For fixed $f$, $\Inj_T(f)$ holds precisely for $T < \tau(f)$, and $\tau(f) \le n$, so
$\#\{T < n : \Inj_T(f)\} = \tau(f)$. Exchange summation order.
\end{proof}

\begin{theorem}[Average lower bound]\label{thm:avglow}
For every $T$ with $T(T+1) \le n$ we have $\sum_f \tau(f) \ge (T+1) n^n/2$. Taking
$T+1 = \lfloor\sqrt n\rfloor$: the average first closure time is at least
$\lfloor\sqrt n\rfloor/2$.
\end{theorem}

\begin{proof}
Every collision-free $f$ at level $T$ has $\tau(f) \ge T+1$, and there are at least $n^n/2$ of
them.
\end{proof}

\begin{theorem}[Analytic core]\label{thm:analytic}
For $n \ge 1$, $\ \displaystyle\sum_{T=0}^{n-1}\exp\!\Big(-\frac{T(T+1)}{2n}\Big) \le
3\big(\lfloor\sqrt n\rfloor + 1\big)$.
\end{theorem}

\begin{proof}[Proof sketch]
Put $m = \lfloor\sqrt n\rfloor + 1$ and cut $[0,n)$ into blocks of length $m$. On the $k$-th
block, $T \ge km$ gives $T(T+1)/(2n) \ge k^2m^2/(2n) \ge k/2$ since $m^2 \ge n$ and
$k^2 \ge k$; so the block sum is at most $m e^{-k/2}$. Summing the geometric series with ratio
$e^{-1/2} \le 0.61$ contributes a factor $1/(1-0.61) < 3$.
\end{proof}

\begin{theorem}[$\Theta(\sqrt n)$]\label{thm:theta}
$\displaystyle \lfloor\sqrt n\rfloor\,\frac{n^n}{2} \;\le\; \sum_f \tau(f) \;\le\;
3\big(\lfloor\sqrt n\rfloor+1\big) n^n$. On $\Z/p$ the average first cycle closure --- the only
factor-revealing event --- lies between $\sqrt p/2$ and $3(\sqrt p + 1)$, i.e.\
$\Theta(N^{1/4})$ for balanced $N = pq$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:avglow} for the lower half; Theorem~\ref{thm:layer}, then the upper tail of
Theorem~\ref{thm:tails} termwise, then Theorem~\ref{thm:analytic} for the upper half.
\end{proof}

\subsection{Cycle detection inherits the barrier}

\begin{theorem}[A tortoise-and-hare match is a collision]
If $f^{[i]}(a) = f^{[2i]}(a)$ with $i > 0$ then $\tau(f) \le 2i$.
\end{theorem}

\begin{theorem}[Average barrier for the rho loop]
Let $\mathrm{ftime}(f)$ be any tortoise-and-hare match time for $f$ (in particular the first
one, which the Pollard rho loop returns). Then
$\sum_f \mathrm{ftime}(f) \ge \lfloor\sqrt n\rfloor\, n^n/4$: the average is at least
$\lfloor\sqrt n\rfloor/4$, and on $\Z/p$ at least $\sqrt p/4$.
\end{theorem}

Generic nonlinear $N$-explicit iteration therefore costs $\Theta(\sqrt p) = \Theta(N^{1/4})$ on
average, and no cycle-detection variant improves the exponent.

\section{Regime (b), circularity, and the straight-line dichotomy}\label{sec:sle}

\begin{theorem}[Pollard $p-1$ reveal criterion]\label{thm:pm1}
For $N = pq$, $a \in \Z$, $M \in \mathbb{N}$:
$\ \Rev_{pq}(a^M-1) \iff \big(\ord_p(a) \mid M\big) \XOR \big(\ord_q(a) \mid M\big)$.
\end{theorem}

\begin{theorem}[Exact reveal time]\label{thm:pm1exact}
If $a$ is invertible modulo both $p$ and $q$ and $\ord_p(a) \neq \ord_q(a)$, then the least
$M > 0$ with $\Rev_{pq}(a^M-1)$ is exactly $M^\ast = \min(\ord_p a, \ord_q a)$.
\end{theorem}

\begin{proof}[Proof sketch]
($\ge$) A reveal forces one order to divide $M$, hence $M \ge M^\ast$. ($\le$) At
$M = M^\ast$, say $M^\ast = \ord_p a$: then $\ord_p a \mid M^\ast$ while $\ord_q a \nmid M^\ast$
since $\ord_q a > M^\ast$, so the exclusive-or of Theorem~\ref{thm:pm1} holds.
\end{proof}

The cost of regime (b) is thus \emph{precisely} an invariant of the hidden factors. On
$N = 341371 = 631\cdot 541$ with $a = 2$ we have $\ord_{631}(2) = 45$, $\ord_{541}(2) = 540$, so
$M^\ast = 45$ and $\gcd(2^{45}-1,N) = 631$; both $630 = 2\cdot3^2\cdot5\cdot7$ and
$540 = 2^2\cdot3^3\cdot5$ are smooth. This is the honest boundary of the no-go: there exist
moduli on which an $N$-independent iteration wins quickly, but nothing visible in $N$ says so in
advance.

\begin{theorem}[Barrier 6: circularity]
Let $N > 1$ and $e \in \Z$ with $N \mid e(e-1)$, $N \nmid e$, $N \nmid e-1$ --- a nontrivial
idempotent mod $N$. Then $1 < \gcd(e,N) < N$.
\end{theorem}

\begin{proof}[Proof sketch]
$\gcd(e,N) < N$ since $N \nmid e$; and if $\gcd(e,N)=1$ then $N \mid e(e-1)$ forces
$N \mid e-1$, a contradiction.
\end{proof}

\begin{definition}
A \emph{straight-line expression} in one variable is generated by
$e ::= x \mid c\ (c \in \Z) \mid e_1+e_2 \mid e_1-e_2 \mid e_1\cdot e_2 \mid e^{-1}$,
interpreted in any commutative ring, with $e^{-1}$ interpreted by the total inverse function
returning $0$ on non-units. All inversions \emph{succeed at $x$} if every inversion node is
applied to a unit when evaluated at $x$; $e$ is \emph{division-free} if it has no inversion
node.
\end{definition}

A division-free program is literally an integer polynomial, so every theorem of
\S\ref{sec:fact1}--\S\ref{sec:birthday} applies to it verbatim.

\begin{theorem}[CRT-blindness of successful computations]\label{thm:evalhom}
Let $\varphi : R \to S$ be a ring homomorphism and $e$ a straight-line expression all of whose
inversions succeed at $x \in R$. Then $\varphi(e(x)) = e(\varphi(x))$.
\end{theorem}

\begin{proof}[Proof sketch]
Structural induction. Constants, the variable and $+,-,\times$ are handled by the homomorphism
axioms; for an inversion applied to a unit $u$, $\varphi(u)$ is a unit and
$\varphi(u^{-1}) = \varphi(u)^{-1}$, the total-inverse convention agreeing with the honest
inverse at units.
\end{proof}

\begin{corollary}
For coprime $m_1, m_2$, the orbit of a straight-line iteration in $\Z/(m_1m_2)$ maps under the
Chinese Remainder isomorphism to the pair of orbits of \emph{the same} program in $\Z/m_1$ and
$\Z/m_2$.
\end{corollary}

\begin{theorem}[A non-unit is a factorisation]\label{thm:nonunit}
If $N > 1$ and $v \in \Z/N$ is neither $0$ nor a unit, then its integer representative reveals
a nontrivial factor of $N$.
\end{theorem}

\begin{theorem}[Straight-line rigidity dichotomy]\label{thm:dichotomy}
Let $N>1$, let $e$ be a straight-line expression, and let $x \in \Z/N$. Then at least one of:
\begin{enumerate}
\item the computation is \emph{CRT-blind}: $\varphi(e(x)) = e(\varphi(x))$ for every ring
homomorphism $\varphi$ out of $\Z/N$, in particular for both CRT projections, so the same
program computes both components and nothing about the splitting is produced; or
\item some intermediate value $v$ of the computation is not a unit, and then $v=0$ or $v$
reveals a nontrivial factor of $N$.
\end{enumerate}
\end{theorem}

\begin{proof}
If all inversions succeed, Theorem~\ref{thm:evalhom} gives (1). Otherwise an inversion node is
applied to a non-unit $v$; if $v \neq 0$, Theorem~\ref{thm:nonunit} gives a factor.
\end{proof}

Leaving polynomiality requires dividing; dividing successfully keeps you blind; dividing
unsuccessfully hands you the factorisation. There is no third option.

\section{The three regimes}

\begin{center}
\begin{tabular}{@{}llll@{}}
\toprule
Regime & Example & Reveal time & Cost \\
\midrule
(a) generic nonlinear & $x \mapsto x^2+1$ & first exclusive closure &
  $\Theta(\sqrt p) = \Theta(N^{1/4})$, sharp \\
(b) smoothness-dependent & $\gcd(a^M-1,N)$ & $\min(\ord_p a, \ord_q a)$ &
  hidden invariant of $p,q$ \\
(c) structurally simple & $x \mapsto x+1$; constants & $\ge \min(p,q)$; never &
  $\ge \sqrt{N/2}$; superpolynomial \\
\bottomrule
\end{tabular}
\end{center}

No case is polynomial in $\log N$, and (b) is polynomial only for moduli whose smoothness is not
detectable from $N$.

\section{Verification on a concrete modulus}

Take $N = 341371 = 631\cdot541$, $f(x) = x^2+1$, seed $2$; the trajectory mod $N$ begins
$2, 5, 26, 677, \dots$.

\begin{observation}
The pair $(s,t) = (23,36)$ satisfies $\gcd(x_{36}-x_{23}, N) = 631$; moreover
$631 \mid x_{36}-x_{23}$ and $541 \nmid x_{36}-x_{23}$, so exactly one branch of the
exclusive-or of Theorem~\ref{thm:revealchar} holds, and the reveal is exactly the closure of the
mod-$631$ orbit while the mod-$541$ orbit has not yet closed.
\end{observation}

\begin{observation}[Minimality]
No pair $s<t\le 35$ reveals a factor. This is established not by a brute-force gcd search but
through Theorem~\ref{thm:norev}: it suffices to check that both reduced orbits are injective on
$\{0,\dots,35\}$. Hence the first reveal is at $t = 36$, while $\sqrt{631}\approx 25.1$ (the
birthday scale) and $\log_2 N \approx 18.4$.
\end{observation}

\begin{observation}[Regime (b) on the same modulus]
$\ord_{631}(2) = 45$ divides $45$ and $\ord_{541}(2) = 540$ does not, so
$\gcd(2^{45}-1,N) = 631$ and by Theorem~\ref{thm:pm1exact} the exact reveal time is $45$.
\end{observation}

\paragraph{Scaling experiment.} Running $x \mapsto x^2+1$ from seed $2$ on random balanced
semiprimes and recording the first revealing pair $(s,t)$, with $r = t/\sqrt{\min(p,q)}$:

