"""Algorithm B — Exact Birthday Counting Law with Two-Sided Threshold Bounds.

Evaluates, for an n-element state space, the exact number of maps whose orbit prefix
of length T+1 is collision-free, together with the Weierstrass lower bound, the
Gaussian upper bound, and the layer-cake average closure time.
"""

from __future__ import annotations

import math
from math import isqrt
from typing import List, Tuple


def birthday_count(n: int, T: int) -> int:
    """Exact count (n-1)(n-2)...(n-T) * n^(n-T) of collision-free maps."""
    if T >= n:
        return 0
    falling = 1
    for i in range(1, T + 1):
        falling *= n - i
    return falling * n ** (n - T)


def birthday_fraction(n: int, T: int) -> float:
    """Exact collision-free fraction prod_{i=1..T} (1 - i/n)."""
    frac = 1.0
    for i in range(1, T + 1):
        frac *= 1.0 - i / n
    return frac


def two_sided_bounds(n: int, T: int) -> Tuple[float, float]:
    """(1 - T(T+1)/2n, exp(-T(T+1)/2n)): Weierstrass below, Gaussian above."""
    s = T * (T + 1) / (2.0 * n)
    return 1.0 - s, math.exp(-s)


def threshold_window(n: int) -> Tuple[int, int]:
    """Largest T with T(T+1) <= n (fraction >= 1/2) and least T with 4n <= T(T+1)
    (fraction <= 1/4)."""
    lo = 0
    while (lo + 1) * (lo + 2) <= n:
        lo += 1
    hi = 0
    while hi * (hi + 1) < 4 * n:
        hi += 1
    return lo, hi


def average_closure_time(n: int) -> float:
    """Layer cake: sum_f tau(f) = sum_{T<n} A_T; divide by n^n."""
    return sum(birthday_count(n, T) for T in range(n)) / n ** n


def gaussian_tail_sum_bound(n: int) -> float:
    """The analytic core: sum_{T<n} exp(-T(T+1)/2n) <= 3 (floor(sqrt n) + 1)."""
    return 3.0 * (isqrt(n) + 1)


def report(n: int, ts: List[int]) -> None:
    lo, hi = threshold_window(n)
    print(f"n = {n}   threshold window: fraction >= 1/2 for T <= {lo}, "
          f"<= 1/4 for T >= {hi}   (sqrt n = {math.sqrt(n):.1f})")
    print(f"{'T':>6} {'lower':>12} {'exact':>12} {'upper':>12}")
    for T in ts:
        low, up = two_sided_bounds(n, T)
        print(f"{T:>6} {max(low, 0.0):>12.6f} {birthday_fraction(n, T):>12.6f} {up:>12.6f}")


if __name__ == "__main__":
    report(10007, [10, 50, 100, 200, 300])
    print()
    print(f"{'n':>5} {'avg closure':>13} {'sqrt(n)/2':>11} {'3(sqrt n+1)':>13}")
    for n in (4, 8, 12, 20, 40, 80):
        print(f"{n:>5} {average_closure_time(n):>13.4f} {isqrt(n) / 2:>11.4f} "
              f"{3 * (isqrt(n) + 1):>13.4f}")

"""Algorithm C — Exact Smoothness-Regime Reveal Time via Multiplicative Orders.

For N = p*q and a base a invertible modulo both factors with distinct multiplicative
orders, the least exponent M > 0 for which gcd(a^M - 1, N) is a nontrivial factor is
exactly min(ord_p a, ord_q a).  This module computes it and certifies it.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, Optional, Tuple


def prime_factors(n: int) -> Dict[int, int]:
    factors: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors


def euler_phi(n: int) -> int:
    result = n
    for p in prime_factors(n):
        result -= result // p
    return result


def multiplicative_order(a: int, m: int) -> int:
    """Least k > 0 with a^k = 1 (mod m), by descending through the prime factors of phi(m)."""
    if gcd(a, m) != 1:
        raise ValueError("base must be invertible")
    order = euler_phi(m)
    for p, e in prime_factors(order).items():
        for _ in range(e):
            if pow(a, order // p, m) == 1:
                order //= p
            else:
                break
    return order


def exact_pm1_reveal_time(p: int, q: int, a: int) -> Optional[Tuple[int, int]]:
    """Return (M*, factor) with M* = min(ord_p a, ord_q a), or None if the two orders
    coincide (in which case the exclusive-or never fires and no exponent reveals)."""
    op, oq = multiplicative_order(a % p, p), multiplicative_order(a % q, q)
    if op == oq:
        return None
    m_star = min(op, oq)
    return m_star, (p if op < oq else q)


def certify(p: int, q: int, a: int) -> str:
    n = p * q
    result = exact_pm1_reveal_time(p, q, a)
    if result is None:
        return "orders coincide: the exclusive-or never fires"
    m_star, factor = result
    g = gcd(pow(a, m_star, n) - 1, n)
    earlier = [M for M in range(1, m_star) if 1 < gcd(pow(a, M, n) - 1, n) < n]
    return (f"M* = {m_star}, gcd(a^M* - 1, N) = {g} (expected {factor}); "
            f"no earlier exponent reveals: {earlier == []}")


if __name__ == "__main__":
    print(certify(631, 541, 2))
    print("ord_631(2) =", multiplicative_order(2, 631),
          " ord_541(2) =", multiplicative_order(2, 541))
